 owner=read('.superpowers/m80-signedin-manager-observation-20260925-001.json')
 matches=[x for x in membership['existingSyntheticCompanyManagers'] if all(x[k]==owner[k] for k in ['companyId','managerUserId','managerRole'])];assert len(matches)==1
 head=subprocess.check_output(['git','rev-parse','HEAD']).decode().strip();assert head==ci['sha']==ci['pr_head'] and ci['state']=='open'
 assert len(ci['checks'])==6 and all(c['status']=='completed' and c['conclusion']=='success' for c in ci['checks'])
 assert b['sourceApplicationStateSha256']==db['applicationStateSha256']==membership['applicationStateSha256']
 assert rr['completedAt']==pr['completedAt']==mr['completedAt'] and rr['sourceBackupReceiptSha256']==pin(backupp)['sha256']
 candidate='40c4ac822ef2d045457ade7dd63d471813178c8f3a585425be58eb81013de59b';migration='0ee148b366e803e8cf28187393f9e5a6f19b29f5bb54578e359db7cbcd795e35'
 target={'observedAt':iso(provider['observed_at']),'observationPhase':'healthy_pre_stop_baseline','projectRef':db['projectRef'],'environmentId':provider['environment'],'serviceId':provider['service'],'deploymentId':row['id'],'deploymentStatus':'SUCCESS','deployedCommitSha':row['meta']['commitHash'],'deployedImageSha256':row['meta']['imageDigest'].removeprefix('sha256:'),'targetClassification':'private_synthetic_staging','syntheticDataOnlyVerified':True,'schemaVersion':21,'migrationReceiptCount':21,'observedNonReceiptTableCount':db['observedNonReceiptTableCount'],'observedNonReceiptTables':db['observedNonReceiptTables'],'historicalReferenceNonReceiptTableCount':120,'applicationReadinessSchemaVersion':21,'applicationStateSha256':db['applicationStateSha256'],'automaticDeploymentsPaused':True,'writeQuiescenceRequiredBeforeExecution':True}
 target['observationReceipt']=write('target',{'profile':'neuvetra.m80.foundation-hosted-target-observation.v1',**target})
 pub={'reviewedHeadCommitSha':head,'headObservedAt':iso(ci['observed_at']),'checksObservedAt':iso(ci['observed_at']),'requiredChecks':ci['checks'],'publicationReviewVerdict':'pass','integrationAcceptanceVerdict':'pass'}
 pub['publicationReview']=write('publication',{'profile':'neuvetra.m80.foundation-hosted-publication-review.v1','observedAt':pub['headObservedAt'],'verdict':'pass','reviewedHeadCommitSha':head,'requiredChecks':ci['checks']})
 pub['integrationAcceptance']=write('integration',{'profile':'neuvetra.m80.foundation-hosted-integration-acceptance.v1','observedAt':pub['headObservedAt'],'verdict':'pass','reviewedHeadCommitSha':head,'candidateSha256':candidate,'migrationSha256':migration,'runtimeIntegrationAccepted':True,'uiIntegrationAccepted':True})
 backup={k:v for k,v in b.items() if k not in ['profile','projectRef']};backup['backupReceipt']=pin(backupp)
 rehearsal={'completedAt':rr['completedAt'],'disposableDatabaseName':rr['disposableDatabaseName'],'hostedEvidence':False,'sourceSchemaVersion':21,'targetSchemaVersion':22,'sourceBackupReceiptSha256':pin(backupp)['sha256'],'migrationSha256':migration,'sourceObservedNonReceiptTableCount':pr['observedNonReceiptTableCount'],'sourceObservedNonReceiptTablesSha256':pr['observedNonReceiptTablesSha256'],'historicalReferenceNonReceiptTableCount':120,'oldMigrationReceiptCount':21,**{k:pr[k] for k in ['sourceContentSha256','restoredContentSha256','sourceMetadataSha256','restoredMetadataSha256','oldContentExact','oldMetadataExact']},**{k:mr[k] for k in ['expectedNewTables','expectedNewTableRowCounts','releaseRecordsExactFourHeld','forcedRlsVerified','runtimeSelectOnlyVerified','runtimeDirectWritesDenied','operatorAdmissionNotExecuted','allConnectionsClosed']},'restoreReceipt':pin(rp),'preservationReceipt':pin(pp),'migrationReceipt':pin(mp)}
